}
```

showModal.description:
Shows a dialog with custom buttons. Currently 1–2 buttons are supported, and parameters must be evaluated in advance. The cancel button added by desktop clients returns an empty `selectedId`.

Result schema:
```json
{
  "oneOf": [
    {
      "type": "object",
      "properties": {
        "status": {
          "const": "success"
        },
        "data": {
          "additionalProperties": false,
          "properties": {
            "selectedId": {
              "maxLength": 4096,
              "type": "string"
            }
          },
          "required": [
            "selectedId"
          ],
          "type": "object"
        }
      },
      "required": [
        "status",
        "data"
      ],
      "additionalProperties": false
    },
    {
      "type": "object",
      "properties": {
        "status": {
          "const": "failed"
        }
      },
      "required": [
        "status"
      ],
      "additionalProperties": false
    }
  ]
}
```
